                      if (IntCycle == 1'b1 && IStatus == 2'b01 ) 
                        begin
                          IR_n = 8'b11111111;
                        end 
                      else if (Halt_FF == 1'b1 || (IntCycle == 1'b1 && IStatus == 2'b10) || NMICycle == 1'b1 ) 
                        begin
                          IR_n = 8'b00000000;
			  TmpAddr_n[7:0] = dinst; // Special M1 vector fetch
                        end 
                      else 
                        begin
                          IR_n = dinst;
                        end

                      ISet_n = 2'b00;
                      if (Prefix != 2'b00 ) 
                        begin
                          if (Prefix == 2'b11 ) 
                            begin
                              if (IR[5] == 1'b1 ) 
                                begin
                                  XY_State_n = 2'b10;
                                end 
                              else 
                                begin
                                  XY_State_n = 2'b01;
                                end
                            end 
                          else 
                            begin
                              if (Prefix == 2'b10 ) 
                                begin
                                  XY_State_n = 2'b00;
                                  XY_Ind_n = 1'b0;
                                end
                              ISet_n = Prefix;
                            end
                        end 
                      else 
                        begin
                          XY_State_n = 2'b00;
                          XY_Ind_n = 1'b0;
                        end
                    end // if (tstate == 2 && wait_n == 1'b1 )
                  

                end 
              else 
                begin
                  // either (mcycle > 1) OR (mcycle == 1 AND tstate > 3)

                  if (mcycle[5] ) 
                    begin
                      XY_Ind_n = 1'b1;
                      if (Prefix == 2'b01 ) 
                        begin
                          ISet_n = 2'b01;
                        end
                    end
                  
                  if (T_Res == 1'b1 ) 
                    begin
                      BTR_r_n = (I_BT || I_BC || I_BTR) && ~ No_BTR;
                      if (Jump == 1'b1 ) 
                        begin
                          A_n[15:8] = DI_Reg;
                          A_n[7:0] = TmpAddr[7:0];
                          PC_n[15:8] = DI_Reg;
                          PC_n[7:0] = TmpAddr[7:0];
                        end 
                      else if (JumpXY == 1'b1 ) 
                        begin
                          A_n = RegBusC;
                          PC_n = RegBusC;
                        end else if (Call == 1'b1 || RstP == 1'b1 ) 
                          begin
                            A_n = TmpAddr;
                            PC_n = TmpAddr;
                          end 
                        else if (last_mcycle && NMICycle == 1'b1 ) 
                          begin
                            A_n = 16'b0000000001100110;
                            PC_n = 16'b0000000001100110;
                          end 
                        else if (mcycle[2] && IntCycle == 1'b1 && IStatus == 2'b10 ) 
                          begin
                            A_n[15:8] = I;
                            A_n[7:0] = TmpAddr[7:0];
                            PC_n[15:8] = I;
                            PC_n[7:0] = TmpAddr[7:0];
                          end 
                        else 
                          begin
                            case (Set_Addr_To)
                              aXY :
                                begin
                                  if (XY_State == 2'b00 ) 
                                    begin
                                      A_n = RegBusC;
                                    end 
                                  else 
                                    begin
                                      if (NextIs_XY_Fetch == 1'b1 )
                                        begin
                                          A_n = PC;
                                        end 
                                      else 
                                        begin
                                          A_n = TmpAddr;
                                        end
                                    end // else: !if(XY_State == 2'b00 )
                                end // case: aXY
                              
                              aIOA :
                                begin
                                  if (Mode == 3 ) 
                                    begin
                                      // Memory map I/O on GBZ80
                                      A_n[15:8] = 8'hFF;
                                    end 
                                  else if (Mode == 2 ) 
                                    begin
                                      // Duplicate I/O address on 8080
                                      A_n[15:8] = DI_Reg;
                                    end 
                                  else 
                                    begin
                                      A_n[15:8] = ACC;
                                    end
                                  A_n[7:0] = DI_Reg;
                                end // case: aIOA

                              
                              aSP :
                                begin
                                  A_n = SP;
                                end
                              
                              aBC :
                                begin
                                  if (Mode == 3 && iorq_i == 1'b1 ) 
                                    begin
                                      // Memory map I/O on GBZ80
                                      A_n[15:8] = 8'hFF;
                                      A_n[7:0] = RegBusC[7:0];
                                    end 
                                  else 
                                    begin
                                      A_n = RegBusC;
                                    end
                                end // case: aBC
                              
                              aDE :
                                begin
                                  A_n = RegBusC;
                                end
                              
                              aZI :
                                begin                                  
                                  if (Inc_WZ == 1'b1 ) 
                                    begin
                                      A_n = TmpAddr + 1;
                                    end 
                                  else 
                                    begin
                                      A_n[15:8] = DI_Reg;
                                      A_n[7:0] = TmpAddr[7:0];
                                    end
                                end // case: aZI
                              
                              default   :
                                begin                                    
                                  A_n = PC;
                                end
                            endcase // case(Set_Addr_To)
                            
                          end // else: !if(mcycle[2] && IntCycle == 1'b1 && IStatus == 2'b10 )
                      

                      Save_ALU_r_n = Save_ALU;
                      ALU_Op_r_n = ALU_Op;
                      
                      if (I_CPL == 1'b1 ) 
                        begin
                          // CPL
                          ACC_n = ~ ACC;
                          F_n[Flag_Y] = ~ ACC[5];
                          F_n[Flag_H] = 1'b1;
                          F_n[Flag_X] = ~ ACC[3];
                          F_n[Flag_N] = 1'b1;
                        end
                      if (I_CCF == 1'b1 ) 
                        begin
                          // CCF
                          F_n[Flag_C] = ~ F[Flag_C];
                          F_n[Flag_Y] = ACC[5];
                          F_n[Flag_H] = F[Flag_C];
                          F_n[Flag_X] = ACC[3];
                          F_n[Flag_N] = 1'b0;
                        end
                      if (I_SCF == 1'b1 ) 
                        begin
                          // SCF
                          F_n[Flag_C] = 1'b1;
                          F_n[Flag_Y] = ACC[5];
                          F_n[Flag_H] = 1'b0;
                          F_n[Flag_X] = ACC[3];
                          F_n[Flag_N] = 1'b0;
                        end
                    end // if (T_Res == 1'b1 )
                  

                  if (tstate[2] && wait_n == 1'b1 ) 
                    begin
                      if (ISet == 2'b01 && mcycle[6] ) 
                        begin
                          IR_n = dinst;
                        end
                      if (JumpE == 1'b1 ) 
                        begin
                          PC_n = PC16;
                        end 
                      else if (Inc_PC == 1'b1 ) 
                        begin
                          //PC <= `TV80DELAY PC + 1;
                          PC_n = PC16;
                        end
                      if (BTR_r == 1'b1 ) 
                        begin
                          //PC <= `TV80DELAY PC - 2;
                          PC_n = PC16;
                        end
                      if (RstP == 1'b1 ) 
                        begin
                          TmpAddr_n = { 10'h0, IR[5:3], 3'h0 };
                          //TmpAddr <= `TV80DELAY (others =>1'b0);
                          //TmpAddr[5:3] <= `TV80DELAY IR[5:3];
                        end
                    end
                  if (tstate[3] && mcycle[5] ) 
                    begin
                      TmpAddr_n = SP16;
                    end

                  if ((tstate[2] && wait_n == 1'b1) || (tstate[4] && mcycle[0]) ) 
                    begin
                      if (IncDec_16[2:0] == 3'b111 ) 
                        begin
                          SP_n = SP16;
                        end
                    end

                  if (LDSPHL == 1'b1 ) 
                    begin
                      SP_n = RegBusC;
                    end
                  if (ExchangeAF == 1'b1 ) 
                    begin
                      Ap_n = ACC;
                      ACC_n = Ap;
                      Fp_n = F;
                      F_n = Fp;
                    end
                  if (ExchangeRS == 1'b1 ) 
                    begin
                      Alternate_n = ~ Alternate;
                    end
                end // else: !if(mcycle  == 3'b001 && tstate(2) == 1'b0 )
              

              if (tstate[3] ) 
                begin
                  if (LDZ == 1'b1 ) 
                    begin
                      TmpAddr_n[7:0] = DI_Reg;
                    end
                  if (LDW == 1'b1 ) 
                    begin
                      TmpAddr_n[15:8] = DI_Reg;
                    end

                  if (Special_LD[2] == 1'b1 ) 
                    begin
                      case (Special_LD[1:0])
                        2'b00 :
                          begin
                            ACC_n = I;
                            F_n[Flag_P] = IntE_FF2;
			    F_n[Flag_Z] = (I == 0);
			    F_n[Flag_S] = I[7];
			    F_n[Flag_H] = 0;
			    F_n[Flag_N] = 0; 
                          end
                        
                        2'b01 :
                          begin
                            // karabas: LD A,R gives R and its S / Z (were 0 and those of I)
                            ACC_n = R;
                            F_n[Flag_P] = IntE_FF2;
			    F_n[Flag_Z] = (R == 0);
			    F_n[Flag_S] = R[7];
			    F_n[Flag_H] = 0;
			    F_n[Flag_N] = 0; 
                          end
                        
                        2'b10 :
                          I_n = ACC;

 			// karabas: LD R,A always (was only with TV80_REFRESH)
                        default :
                          R_n = ACC;
                      endcase
                    end
                end // if (tstate == 3 )
              

              if ((I_DJNZ == 1'b0 && Save_ALU_r == 1'b1) || ALU_Op_r == 4'b1001 ) 
                begin
                  if (Mode == 3 ) 
                    begin
                      F_n[6] = F_Out[6];
                      F_n[5] = F_Out[5];
                      F_n[7] = F_Out[7];
                      if (PreserveC_r == 1'b0 ) 
                        begin
                          F_n[4] = F_Out[4];
                        end
                    end 
                  else 
                    begin
                      F_n[7:1] = F_Out[7:1];
                      if (PreserveC_r == 1'b0 ) 
                        begin
                          F_n[Flag_C] = F_Out[0];
                        end
                    end
                end // if ((I_DJNZ == 1'b0 && Save_ALU_r == 1'b1) || ALU_Op_r == 4'b1001 )
              
              if (T_Res == 1'b1 && I_INRC == 1'b1 ) 
                begin
                  F_n[Flag_H] = 1'b0;
                  F_n[Flag_N] = 1'b0;
                  if (DI_Reg[7:0] == 8'b00000000 ) 
                    begin
                      F_n[Flag_Z] = 1'b1;
                    end 
                  else 
                    begin
                      F_n[Flag_Z] = 1'b0;
                    end
                  F_n[Flag_S] = DI_Reg[7];
                  F_n[Flag_P] = ~ (^DI_Reg[7:0]);
                end // if (T_Res == 1'b1 && I_INRC == 1'b1 )
              

              if (tstate[1] && Auto_Wait_t1 == 1'b0 ) 
                begin
                  dout_n = BusB;
                  if (I_RLD == 1'b1 ) 
                    begin
                      dout_n[3:0] = BusA[3:0];
                      dout_n[7:4] = BusB[3:0];
                    end
                  if (I_RRD == 1'b1 ) 
                    begin
                      dout_n[3:0] = BusB[7:4];
                      dout_n[7:4] = BusA[3:0];
                    end
                end

              if (T_Res == 1'b1 ) 
                begin
                  Read_To_Reg_r_n[3:0] = Set_BusA_To;
                  Read_To_Reg_r_n[4] = Read_To_Reg;
                  if (Read_To_Acc == 1'b1 ) 
                    begin
                      Read_To_Reg_r_n[3:0] = 4'b0111;
                      Read_To_Reg_r_n[4] = 1'b1;
                    end
                end

              if (tstate[1] && I_BT == 1'b1 )
                begin
                  F_n[Flag_X] = ALU_Q[3];
                  F_n[Flag_Y] = ALU_Q[1];
                  F_n[Flag_H] = 1'b0;
                  F_n[Flag_N] = 1'b0;
                end
              if (tstate[1] && I_BC == 1'b1 )
                begin
                  F_n[Flag_X] = cpi_xy_n[3];
                  F_n[Flag_Y] = cpi_xy_n[1];
                end
              if (I_BC == 1'b1 || I_BT == 1'b1 )
                begin
                  F_n[Flag_P] = IncDecZ;
                end

              if ((tstate[1] && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) ||
                  (Save_ALU_r == 1'b1 && ALU_Op_r != 4'b0111) ) 
                begin
                  case (Read_To_Reg_r)
                    5'b10111 :
                      ACC_n = Save_Mux;
                    5'b10110 :
                      dout_n = Save_Mux;
                    5'b11000 :
                      SP_n[7:0] = Save_Mux;
                    5'b11001 :
                      SP_n[15:8] = Save_Mux;
                    5'b11011 :
                      F_n = Save_Mux;
                    default : ;
                  endcase
                end // if ((tstate == 1 && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) ||...              
            end // if (ClkEn == 1'b1 )         
        end // else: !if(reset_n == 1'b0 )
      PC_m[th] <= PC_n;
      A_m[th] <= A_n;
      TmpAddr_m[th] <= TmpAddr_n;
      IR_m[th] <= IR_n;
      ISet_m[th] <= ISet_n;
      XY_State_m[th] <= XY_State_n;
      IStatus_m[th] <= IStatus_n;
      mcycles_m[th] <= mcycles_n;
      dout_m[th] <= dout_n;
      ACC_m[th] <= ACC_n;
      F_m[th] <= F_n;
      Ap_m[th] <= Ap_n;
      Fp_m[th] <= Fp_n;
      I_m[th] <= I_n;
      R_m[th] <= R_n;
      SP_m[th] <= SP_n;
      Alternate_m[th] <= Alternate_n;
      Read_To_Reg_r_m[th] <= Read_To_Reg_r_n;
      Arith16_r_m[th] <= Arith16_r_n;
      BTR_r_m[th] <= BTR_r_n;
      Z16_r_m[th] <= Z16_r_n;
      ALU_Op_r_m[th] <= ALU_Op_r_n;
      Save_ALU_r_m[th] <= Save_ALU_r_n;
      PreserveC_r_m[th] <= PreserveC_r_n;
      XY_Ind_m[th] <= XY_Ind_n;
    end
  

  //-------------------------------------------------------------------------
  //
  // BC('), DE('), HL('), IX && IY
  //
  //-------------------------------------------------------------------------
  always @ (posedge clk)
    begin
      RegAddrA_r_n = RegAddrA_r;
      RegAddrB_r_n = RegAddrB_r;
      RegAddrC_n = RegAddrC;
      IncDecZ_n = IncDecZ;
      RegBusA_r_n = RegBusA_r;
      if (ClkEn == 1'b1 ) 
        begin
          // Bus A / Write
          RegAddrA_r_n = { Alternate, Set_BusA_To[2:1] };
          if (XY_Ind == 1'b0 && XY_State != 2'b00 && Set_BusA_To[2:1] == 2'b10 ) 
            begin
              RegAddrA_r_n = { XY_State[1],  2'b11 };
            end

          // Bus B
          RegAddrB_r_n = { Alternate, Set_BusB_To[2:1] };
          if (XY_Ind == 1'b0 && XY_State != 2'b00 && Set_BusB_To[2:1] == 2'b10 ) 
            begin
              RegAddrB_r_n = { XY_State[1],  2'b11 };
            end

          // Address from register
          RegAddrC_n = { Alternate,  Set_Addr_To[1:0] };
          // Jump (HL), LD SP,HL
          if ((JumpXY == 1'b1 || LDSPHL == 1'b1) ) 
            begin
              RegAddrC_n = { Alternate, 2'b10 };
            end
          if (((JumpXY == 1'b1 || LDSPHL == 1'b1) && XY_State != 2'b00) || (mcycle[5]) ) 
            begin
              RegAddrC_n = { XY_State[1],  2'b11 };
            end

          if (I_DJNZ == 1'b1 && Save_ALU_r == 1'b1 && Mode < 2 ) 
            begin
              IncDecZ_n = F_Out[Flag_Z];
            end
          if ((tstate[2] || (tstate[3] && mcycle[0])) && IncDec_16[2:0] == 3'b100 ) 
            begin
              if (ID16 == 0 ) 
                begin
                  IncDecZ_n = 1'b0;
                end 
              else 
                begin
                  IncDecZ_n = 1'b1;
                end
            end
          
          RegBusA_r_n = RegBusA;
        end
      
      RegAddrA_r_m[th] <= RegAddrA_r_n;
      RegAddrB_r_m[th] <= RegAddrB_r_n;
      RegAddrC_m[th] <= RegAddrC_n;
      IncDecZ_m[th] <= IncDecZ_n;
      RegBusA_r_m[th] <= RegBusA_r_n;
    end // always @ (posedge clk)
  

  always @(/*AUTOSENSE*/Alternate or ExchangeDH or IncDec_16
	   or RegAddrA_r or RegAddrB_r or XY_State or mcycle or tstate)
    begin
      if ((tstate[2] || (tstate[3] && mcycle[0] && IncDec_16[2] == 1'b1)) && XY_State == 2'b00)
        RegAddrA = { Alternate, IncDec_16[1:0] };
      else if ((tstate[2] || (tstate[3] && mcycle[0] && IncDec_16[2] == 1'b1)) && IncDec_16[1:0] == 2'b10)
        RegAddrA = { XY_State[1], 2'b11 };
      else if (ExchangeDH == 1'b1 && tstate[3])
        RegAddrA = { Alternate, 2'b10 };
      else if (ExchangeDH == 1'b1 && tstate[4])
        RegAddrA = { Alternate, 2'b01 };
      else
        RegAddrA = RegAddrA_r;
      
      if (ExchangeDH == 1'b1 && tstate[3])
        RegAddrB = { Alternate, 2'b01 };
      else
        RegAddrB = RegAddrB_r;
    end // always @ *
  

  always @(/*AUTOSENSE*/ALU_Op_r or Auto_Wait_t1 or ExchangeDH
	   or IncDec_16 or Read_To_Reg_r or Save_ALU_r or mcycle
	   or tstate or wait_n)
    begin
      RegWEH = 1'b0;
      RegWEL = 1'b0;
      if ((tstate[1] && ~Save_ALU_r && ~Auto_Wait_t1) ||
          (Save_ALU_r && (ALU_Op_r != 4'b0111)) ) 
        begin
          case (Read_To_Reg_r)
            5'b10000 , 5'b10001 , 5'b10010 , 5'b10011 , 5'b10100 , 5'b10101 :
              begin
                RegWEH = ~ Read_To_Reg_r[0];
                RegWEL = Read_To_Reg_r[0];
              end // UNMATCHED !!
            default : ;
          endcase // case(Read_To_Reg_r)
          
        end // if ((tstate == 1 && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) ||...
      

      if (ExchangeDH && (tstate[3] || tstate[4]) ) 
        begin
          RegWEH = 1'b1;
          RegWEL = 1'b1;
        end

      if (IncDec_16[2] && ((tstate[2] && wait_n && ~mcycle[0]) || (tstate[3] && mcycle[0])) ) 
        begin
          case (IncDec_16[1:0])
            2'b00 , 2'b01 , 2'b10 :
              begin
                RegWEH = 1'b1;
                RegWEL = 1'b1;
              end // UNMATCHED !!
            default : ;
          endcase
        end
    end // always @ *
  

  always @(/*AUTOSENSE*/ExchangeDH or ID16 or IncDec_16 or RegBusA_r
	   or RegBusB or Save_Mux or mcycle or tstate)
    begin
      RegDIH = Save_Mux;
      RegDIL = Save_Mux;

      if (ExchangeDH == 1'b1 && tstate[3] ) 
        begin
          RegDIH = RegBusB[15:8];
          RegDIL = RegBusB[7:0];
        end
      else if (ExchangeDH == 1'b1 && tstate[4] ) 
        begin
          RegDIH = RegBusA_r[15:8];
          RegDIL = RegBusA_r[7:0];
        end
      else if (IncDec_16[2] == 1'b1 && ((tstate[2] && ~mcycle[0]) || (tstate[3] && mcycle[0])) ) 
        begin
          RegDIH = ID16[15:8];
          RegDIL = ID16[7:0];
        end
    end

  tv80o_reg i_reg
    (
     
     .th                   (th),.clk                  (clk),
     .CEN                  (ClkEn && reset_n),
     .WEH                  (RegWEH),
     .WEL                  (RegWEL),
     .AddrA                (RegAddrA),
     .AddrB                (RegAddrB),
     .AddrC                (RegAddrC),
     .DIH                  (RegDIH),
     .DIL                  (RegDIL),
     .DOAH                 (RegBusA[15:8]),
     .DOAL                 (RegBusA[7:0]),
     .DOBH                 (RegBusB[15:8]),
     .DOBL                 (RegBusB[7:0]),
     .DOCH                 (RegBusC[15:8]),
     .DOCL                 (RegBusC[7:0])
     );

  //-------------------------------------------------------------------------
  //
  // Buses
  //
  //-------------------------------------------------------------------------

  always @ (posedge clk)
    begin
      BusB_n = BusB;
      BusA_n = BusA;
      if (ClkEn == 1'b1 ) 
        begin
          case (Set_BusB_To)
            4'b0111 :
              BusB_n = ACC;
            4'b0000 , 4'b0001 , 4'b0010 , 4'b0011 , 4'b0100 , 4'b0101 :
              begin
                if (Set_BusB_To[0] == 1'b1 ) 
                  begin
                    BusB_n = RegBusB[7:0];
                  end 
                else 
                  begin
                    BusB_n = RegBusB[15:8];
                  end
              end
            4'b0110 :
              BusB_n = DI_Reg;
            4'b1000 :
              BusB_n = SP[7:0];
            4'b1001 :
              BusB_n = SP[15:8];
            4'b1010 :
              BusB_n = 8'b00000001;
            4'b1011 :
              BusB_n = F;
            4'b1100 :
              BusB_n = PC[7:0];
            4'b1101 :
              BusB_n = PC[15:8];
            4'b1110 :
              BusB_n = 8'b00000000;
            default :
              BusB_n = 8'h0;
          endcase

          case (Set_BusA_To)
            4'b0111 :
              BusA_n = ACC;
            4'b0000 , 4'b0001 , 4'b0010 , 4'b0011 , 4'b0100 , 4'b0101 :
              begin
                if (Set_BusA_To[0] == 1'b1 )
                  begin
                    BusA_n = RegBusA[7:0];
                  end 
                else 
                  begin
                    BusA_n = RegBusA[15:8];
                  end
              end
            4'b0110 :
              BusA_n = DI_Reg;
            4'b1000 :
              BusA_n = SP[7:0];
            4'b1001 :
              BusA_n = SP[15:8];
            4'b1010 :
              BusA_n = 8'b00000000;
            default :
              BusA_n = 8'h0;
          endcase
        end
      BusB_m[th] <= BusB_n;
      BusA_m[th] <= BusA_n;
    end

  //-------------------------------------------------------------------------
  //
  // Generate external control signals
  //
  //-------------------------------------------------------------------------
  assign rfsh_n = 1'b1;

  always @(/*AUTOSENSE*/BusAck or Halt_FF or I_DJNZ or IntCycle
	   or IntE_FF1 or di or iorq_i or mcycle or tstate)
    begin
      mc = mcycle;
      ts = tstate;
      DI_Reg = di;
      halt_n = ~ Halt_FF;
      busak_n = ~ BusAck;
      intcycle_n = ~ IntCycle;
      IntE = IntE_FF1;
      iorq = iorq_i;
      stop = I_DJNZ;
    end

  //-----------------------------------------------------------------------
  //
  // Syncronise inputs
  //
  //-----------------------------------------------------------------------

  always @ (posedge clk)
    begin : sync_inputs
      BusReq_s_n = BusReq_s;
      INT_s_n = INT_s;
      NMI_s_n = NMI_s;
      Oldnmi_n_n = Oldnmi_n;
      if (~reset_n) 
        begin
          BusReq_s_n = 1'b0;
          INT_s_n = 1'b0;
          NMI_s_n = 1'b0;
          Oldnmi_n_n = 1'b0;
        end 
      else
        begin
          if (cen == 1'b1 ) 
            begin
              BusReq_s_n = ~ busrq_n;
              INT_s_n = ~ int_n;
              if (NMICycle == 1'b1 ) 
                begin
                  NMI_s_n = 1'b0;
                end 
              else if (nmi_n == 1'b0 && Oldnmi_n == 1'b1 ) 
                begin
                  NMI_s_n = 1'b1;
                end
              Oldnmi_n_n = nmi_n;
            end
        end
      BusReq_s_m[th] <= BusReq_s_n;
      INT_s_m[th] <= INT_s_n;
      NMI_s_m[th] <= NMI_s_n;
      Oldnmi_n_m[th] <= Oldnmi_n_n;
    end

  //-----------------------------------------------------------------------
  //
  // Main state machine
  //
  //-----------------------------------------------------------------------

  always @ (posedge clk)
    begin
      mcycle_n = mcycle;
      tstate_n = tstate;
      Pre_XY_F_M_n = Pre_XY_F_M;
      Halt_FF_n = Halt_FF;
      BusAck_n = BusAck;
      NMICycle_n = NMICycle;
      IntCycle_n = IntCycle;
      IntE_FF1_n = IntE_FF1;
      IntE_FF2_n = IntE_FF2;
      No_BTR_n = No_BTR;
      Auto_Wait_t1_n = Auto_Wait_t1;
      Auto_Wait_t2_n = Auto_Wait_t2;
      m1_n_n = m1_n;
      if (reset_n == 1'b0 ) 
        begin
          mcycle_n = 7'b0000001;
          tstate_n = 7'b0000001;
          Pre_XY_F_M_n = 3'b000;
          Halt_FF_n = 1'b0;
          BusAck_n = 1'b0;
          NMICycle_n = 1'b0;
          IntCycle_n = 1'b0;
          IntE_FF1_n = 1'b0;
          IntE_FF2_n = 1'b0;
          No_BTR_n = 1'b0;
          Auto_Wait_t1_n = 1'b0;
          Auto_Wait_t2_n = 1'b0;
          m1_n_n = 1'b1;
        end 
      else
        begin
          if (cen == 1'b1 ) 
            begin
              if (T_Res == 1'b1 ) 
                begin
                  Auto_Wait_t1_n = 1'b0;
                end 
              else 
                begin
		  Auto_Wait_t1_n = Auto_Wait || (iorq_i & ~Auto_Wait_t2);
                end
              Auto_Wait_t2_n = Auto_Wait_t1 & !T_Res;
              No_BTR_n = (I_BT && (~ IR[4] || ~ F[Flag_P])) ||
                        (I_BC && (~ IR[4] || F[Flag_Z] || ~ F[Flag_P])) ||
                        (I_BTR && (~ IR[4] || F[Flag_Z]));
              if (tstate[2] ) 
                begin
                  if (SetEI == 1'b1 ) 
                    begin
                      if (!NMICycle)
                        IntE_FF1_n = 1'b1;
                      IntE_FF2_n = 1'b1;
                    end
                  if (I_RETN == 1'b1 ) 
                    begin
                      IntE_FF1_n = IntE_FF2;
                    end
                end
              if (tstate[3] ) 
                begin
                  if (SetDI == 1'b1 ) 
                    begin
                      IntE_FF1_n = 1'b0;
                      IntE_FF2_n = 1'b0;
                    end
                end
              if (IntCycle == 1'b1 || NMICycle == 1'b1 ) 
                begin
                  Halt_FF_n = 1'b0;
                end
              if (mcycle[0] && tstate[2] && wait_n == 1'b1 ) 
                begin
                  m1_n_n = 1'b1;
                end
              if (BusReq_s == 1'b1 && BusAck == 1'b1 ) 
                begin
                end 
              else 
                begin
                  BusAck_n = 1'b0;
                  if (tstate[2] && wait_n == 1'b0 ) 
                    begin
                    end 
                  else if (T_Res == 1'b1 ) 
                    begin
                      if (Halt == 1'b1 ) 
                        begin
                          Halt_FF_n = 1'b1;
                        end
                      if (BusReq_s == 1'b1 ) 
                        begin
                          BusAck_n = 1'b1;
                        end 
                      else 
                        begin
                          tstate_n = 7'b0000010;
                          if (NextIs_XY_Fetch == 1'b1 ) 
                            begin
                              mcycle_n = 7'b0100000;
                              Pre_XY_F_M_n = mcyc_to_number(mcycle);
                              if (IR == 8'b00110110 && Mode == 0 ) 
                                begin
                                  Pre_XY_F_M_n = 3'b010;
                                end
                            end 
                          else if ((mcycle[6]) || (mcycle[5] && Mode == 1 && ISet != 2'b01) ) 
                            begin
                              mcycle_n = number_to_bitvec(Pre_XY_F_M + 1);
                            end 
                          else if ((last_mcycle) ||
                                   No_BTR == 1'b1 ||
                                   (mcycle[1] && I_DJNZ == 1'b1 && IncDecZ == 1'b1) ) 
                            begin
                              m1_n_n = 1'b0;
                              mcycle_n = 7'b0000001;
                              IntCycle_n = 1'b0;
                              NMICycle_n = 1'b0;
                              if (NMI_s == 1'b1 && Prefix == 2'b00 ) 
                                begin
                                  NMICycle_n = 1'b1;
                                  IntE_FF1_n = 1'b0;
                                end 
                              // karabas: INT as it is at this cen (the end of the last T-state), as T80 351; tv80 took INT_s,
                              // taken a T-state before (an interrupt taken one instruction later now and then; found by
                              // src/sim/tb_t80cmp.v)
                              else if ((IntE_FF1 == 1'b1 && int_n == 1'b0) && Prefix == 2'b00 && SetEI == 1'b0 ) 
                                begin
                                  IntCycle_n = 1'b1;
                                  IntE_FF1_n = 1'b0;
                                  IntE_FF2_n = 1'b0;
                                end
                            end 
                          else 
                            begin
                              mcycle_n = { mcycle[5:0], mcycle[6] };
                            end
                        end
                    end 
                  else 
                    begin   // verilog has no "nor" operator
                      if ( ~(Auto_Wait == 1'b1 && Auto_Wait_t2 == 1'b0) &&
                           ~(IOWait == 1 && iorq_i == 1'b1 && Auto_Wait_t1 == 1'b0) ) 
                        begin
                          tstate_n = { tstate[5:0], tstate[6] };
                        end
                    end
                end
              if (tstate[0]) 
                begin
                  m1_n_n = 1'b0;
                end
            end
        end
      mcycle_m[th] <= mcycle_n;
      tstate_m[th] <= tstate_n;
      Pre_XY_F_M_m[th] <= Pre_XY_F_M_n;
      Halt_FF_m[th] <= Halt_FF_n;
      BusAck_m[th] <= BusAck_n;
      NMICycle_m[th] <= NMICycle_n;
      IntCycle_m[th] <= IntCycle_n;
      IntE_FF1_m[th] <= IntE_FF1_n;
      IntE_FF2_m[th] <= IntE_FF2_n;
      No_BTR_m[th] <= No_BTR_n;
      Auto_Wait_t1_m[th] <= Auto_Wait_t1_n;
      Auto_Wait_t2_m[th] <= Auto_Wait_t2_n;
      m1_n_m[th] <= m1_n_n;
    end

  always @(/*AUTOSENSE*/BTR_r or DI_Reg or IncDec_16 or JumpE or PC
	   or RegBusA or RegBusC or SP or tstate)
    begin
      if (JumpE == 1'b1 ) 
        begin
          PC16_B = { {8{DI_Reg[7]}}, DI_Reg };
        end 
      else if (BTR_r == 1'b1 ) 
        begin
          PC16_B = -2;
        end
      else
        begin
          PC16_B = 1;
        end

      if (tstate[3])
        begin
          SP16_A = RegBusC;
          SP16_B = { {8{DI_Reg[7]}}, DI_Reg };
        end
      else
        begin
          // suspect that ID16 and SP16 could be shared
          SP16_A = SP;
          
          if (IncDec_16[3] == 1'b1)
            SP16_B = -1;
          else
            SP16_B = 1;
        end

      if (IncDec_16[3])  
        ID16_B = -1;
      else
        ID16_B = 1;

      ID16 = RegBusA + ID16_B;
      PC16 = PC + PC16_B;
      SP16 = SP16_A + SP16_B;
    end // always @ *
  

  always @(/*AUTOSENSE*/IntCycle or NMICycle or mcycle)
    begin
      Auto_Wait = 1'b0;
      // karabas: the two automatic wait states only in the M1 of an INT acknowledge, as a Z80 and T80; tv80 had them
      // in the M1 of an NMI too (an NMI answer 2 T-states long; found by src/sim/tb_t80cmp.v)
      if (IntCycle == 1'b1 ) 
        begin
          if (mcycle[0] ) 
            begin
              Auto_Wait = 1'b1;
            end
        end
    end // always @ *
  
  // the outputs of CPU pth (tools/mkctx.py): its registers through the second read port, IORQ / NoRead / Write
  // from a second mcode (only the cone of these three outputs is kept)
  tv80_mcode #(Mode, Flag_C, Flag_N, Flag_P, Flag_X, Flag_H, Flag_Y, Flag_Z, Flag_S) p_mcode
    (
     .IR                   (IR_p),
     .ISet                 (ISet_p),
     .MCycle               (mcycle_p),
     .F                    (F_p),
     .NMICycle             (NMICycle_p),
     .IntCycle             (IntCycle_p),
     .IORQ                 (p_iorq),
     .NoRead               (p_no_read),
     .Write                (p_write)
     );
  assign p_A = A_p;
  assign p_dout = dout_p;
  assign p_m1_n = m1_n_p;
  assign p_mc = mcycle_p;
  assign p_ts = tstate_p;
  assign p_halt_n = ~ Halt_FF_p;
  assign p_intcycle_n = ~ IntCycle_p;

endmodule // T80

